import urllib.parse


class UrlPath:
    NON_EMPTY_PATH = 'non_empty_path'
    ENDS_WITH_SLASH = '/'

    def __init__(self):
        self._segments = []
        self._with_end_tag = False

    @property
    def segments(self):
        return list(self._segments)

    def add(self, segment):
        self._segments.append(self.fix_path(segment))

    def parse(self, path, charset):
        if not path:
            return

        if path.endswith(self.ENDS_WITH_SLASH):
            self._with_end_tag = True

        cleaned_path = self.fix_path(path)
        if not cleaned_path:
            return

        self._append_decoded_segments(cleaned_path, charset)

    def _append_decoded_segments(self, path, charset):
        split_segments = path.split('/')
        for seg in split_segments:
            decoded_seg = urllib.parse.unquote(seg, encoding=charset)
            self._segments.append(decoded_seg)

    @property
    def with_end_tag(self):
        return self._with_end_tag

    @staticmethod
    def fix_path(path):
        if not path:
            return ''

        segment_str = path.strip('/')
        return segment_str
